import random
import itertools
from collections import deque

def max_independent_set_size(n, edges):
    """Find the maximum independent set size using brute force for small graphs."""
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check all subsets of size 5 - if any is independent, alpha >= 5
    for subset in itertools.combinations(range(n), 5):
        is_independent = True
        for i in range(5):
            for j in range(i+1, 5):
                if subset[j] in adj[subset[i]]:
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            return 5  # At least 5

    # Check if there's an independent set of size 4
    for subset in itertools.combinations(range(n), 4):
        is_independent = True
        for i in range(4):
            for j in range(i+1, 4):
                if subset[j] in adj[subset[i]]:
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            return 4

    return 3  # At most 3

def vertex_connectivity(n, edges):
    """Compute vertex connectivity by checking if removing k vertices disconnects the graph."""
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    def is_connected(removed):
        """Check if graph is connected after removing vertices in 'removed'."""
        remaining = [v for v in range(n) if v not in removed]
        if len(remaining) <= 1:
            return True
        visited = set()
        queue = deque([remaining[0]])
        visited.add(remaining[0])
        while queue:
            v = queue.popleft()
            for neighbor in adj[v]:
                if neighbor not in removed and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return len(visited) == len(remaining)

    # Check connectivity after removing 0, 1, 2, 3 vertices
    for k in range(4):
        for removed in itertools.combinations(range(n), k):
            if not is_connected(set(removed)):
                return k
    return 4

def check_graph(n, edges):
    alpha = max_independent_set_size(n, edges)
    kappa = vertex_connectivity(n, edges)
    return alpha, kappa

